// The books, read against themselves, before anything is ordered from them.
//
// Everything the next node does is arithmetic on one number: what the sheet
// says is on the shelf. A sheet is not a shelf. Goods arrive and are never
// booked in, a delivery is ticked off short and nobody raises it, an order
// sits three weeks past its date with the row still saying "open".
//
// Three findings, and the third is the reason this node runs first:
//
//   late delivery    past its expected date, nothing received
//   short receipt    booked in for less than was ordered, no claim raised
//   suspect record   the last count, plus what came in, minus what went out,
//                    is not what the stock column says
//
// Only the third is invisible to the sheet itself: every number in a stock
// sheet agrees with every other number in it, and it takes the physical count
// to catch a row that is lying. A row that is lying is not a row to order
// from, so the planner below refuses to order it and says why.
//
// It always returns at least one item, even when everything is in order. A
// node that returns nothing stops the branch under it, and the branch under
// it is the whole reorder run.

const cfg = $('Set Reorder Policy').first().json;

// Google Sheets hands back one blank item for an empty tab; drop those.
const clean = (bag) => (bag || []).filter((r) => r && Object.keys(r).length);
const products = clean($('Aggregate Product Data').first().json.rows);
const orders = clean($('Aggregate Order Pipeline').first().json.rows);
const sales = clean($('Aggregate Sales History').first().json.rows);
const suppliers = clean($('Aggregate Supplier Terms').first().json.rows);
const history = clean($('Aggregate Reorder History').first().json.rows);

const DAY = 86400000;
const LATE_AFTER = Number(cfg.late_after_days) || 2;
const DRIFT_UNITS = Number(cfg.stock_drift_units) || 0;
const DRIFT_PCT = Number(cfg.stock_drift_pct) || 0;
const CHASE_GAP = Number(cfg.days_between_supplier_chases) || 5;

const num = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const up = (v) => String(v == null ? '' : v).trim().toUpperCase();
const round2 = (v) => Math.round((Number(v) || 0) * 100) / 100;

// "Nordic Packaging AB" and "nordic packaging" are one supplier. The same
// normalisation the payables template uses: off with the legal form, the
// accents and the punctuation.
const LEGAL = /\b(ltd|limited|llc|inc|incorporated|corp|corporation|co|company|gmbh|ag|bv|nv|sa|sas|sarl|srl|spa|oy|ab|as|aps|plc|pty|kg|ug|sl|kft|doo)\b/g;
const key = (name) => String(name || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ')
  .replace(LEGAL, ' ').replace(/\s+/g, ' ').trim();

// A date in a sheet arrives in whatever shape the sheet feels like:
// 2026-03-04, 04/03/2026, or 46085 - which is Sheets' own serial, days since
// 30 December 1899, and reaches a Code node as a plain number. All three end
// up at local midnight, because a delivery date is a calendar day and not an
// instant.
function calendarDay(value) {
  const s = String(value == null ? '' : value).trim();
  if (!s) return null;
  if (/^\d{5}(\.\d+)?$/.test(s)) {
    const d = new Date(Date.UTC(1899, 11, 30) + Math.round(Number(s)) * DAY);
    return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()).getTime();
  }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const dayFirst = a > 12 ? true : b > 12 ? false : String(cfg.date_order) !== 'MDY';
    return new Date(Number(m[3]), (dayFirst ? b : a) - 1, dayFirst ? a : b).getTime();
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

const today = new Date();
today.setHours(0, 0, 0, 0);
const daysSince = (value) => {
  const t = calendarDay(value);
  return t === null ? null : Math.round((today.getTime() - t) / DAY);
};

const OPEN = ['', 'open', 'ordered', 'confirmed', 'partial', 'part received', 'backordered'];
const DONE = ['received', 'closed', 'complete', 'completed'];
const state = (row) => String(row.status || '').trim().toLowerCase();
const isOpen = (row) => OPEN.includes(state(row)) && !String(row.received_on || '').trim();
const isDone = (row) => DONE.includes(state(row)) || !!String(row.received_on || '').trim();

const supplierBy = new Map();
for (const s of suppliers) {
  const k = key(s.supplier_name || s.name);
  if (k) supplierBy.set(k, s);
}

// When we last wrote to each supplier about a late delivery. Without this the
// same three overdue lines go out every morning, which is how a chaser ends
// up in a folder nobody opens.
const lastChase = new Map();
for (const r of history) {
  if (String(r.action || '').toLowerCase() !== 'supplier chase') continue;
  const k = key(r.supplier_name);
  const when = calendarDay(r.run_on);
  if (!k || when === null) continue;
  if (!lastChase.has(k) || when > lastChase.get(k)) lastChase.set(k, when);
}

const out = [];

// --- late deliveries and short receipts, one item per supplier -------------

const issues = new Map();
const issueOf = (row) => {
  const k = key(row.supplier_name);
  if (!issues.has(k)) {
    const s = supplierBy.get(k) || {};
    issues.set(k, {
      supplier_key: k,
      supplier_name: row.supplier_name || s.supplier_name || '(no supplier on the row)',
      supplier_email: String(s.email || '').trim(),
      contact_name: String(s.contact_name || '').trim(),
      late: [],
      short: [],
    });
  }
  return issues.get(k);
};

for (const o of orders) {
  if (state(o) === 'cancelled') continue;
  const ordered = num(o.quantity_ordered);
  const got = num(o.quantity_received);

  if (isOpen(o)) {
    const late = daysSince(o.expected_on);
    if (late !== null && late > LATE_AFTER) {
      issueOf(o).late.push({
        po_number: o.po_number, sku: up(o.sku), quantity: ordered,
        expected_on: o.expected_on, days_late: late,
      });
    }
    continue;
  }

  // A short delivery nobody has claimed is money paid for goods that never
  // arrived. `claim` holds whatever the buyer wrote when they raised it;
  // anything in it means somebody is on it already.
  if (isDone(o) && ordered > 0 && got > 0 && got < ordered && !String(o.claim || '').trim()) {
    issueOf(o).short.push({
      po_number: o.po_number, sku: up(o.sku), ordered, received: got,
      missing: round2(ordered - got), received_on: o.received_on,
    });
  }
}

for (const issue of issues.values()) {
  if (!issue.late.length && !issue.short.length) continue;
  const since = lastChase.has(issue.supplier_key)
    ? Math.round((today.getTime() - lastChase.get(issue.supplier_key)) / DAY) : null;
  if (since !== null && since < CHASE_GAP) continue;

  const lines = [];
  if (issue.late.length) {
    issue.late.sort((a, b) => b.days_late - a.days_late);
    lines.push('Past their date:');
    for (const l of issue.late) {
      lines.push(`  ${l.po_number}  ${l.sku}  ${l.quantity} units  due ${l.expected_on}, ` +
                 `${l.days_late} days ago`);
    }
  }
  if (issue.short.length) {
    if (lines.length) lines.push('');
    lines.push('Booked in short, and never claimed:');
    for (const l of issue.short) {
      lines.push(`  ${l.po_number}  ${l.sku}  ${l.received} of ${l.ordered} received on ` +
                 `${l.received_on}, ${l.missing} missing`);
    }
  }

  out.push({
    json: {
      kind: 'supplier issue',
      supplier_name: issue.supplier_name,
      supplier_email: issue.supplier_email,
      contact_name: issue.contact_name,
      late_count: issue.late.length,
      short_count: issue.short.length,
      po_numbers: [...issue.late, ...issue.short].map((l) => l.po_number).join(', '),
      oldest_days_late: issue.late.reduce((m, l) => Math.max(m, l.days_late), 0),
      subject_line: issue.late.length
        ? `Overdue: ${issue.late.length} order(s) past their date`
        : `Short delivery on ${issue.short[0].po_number}`,
      detail: lines.join('\n'),
      note: `${issue.late.length} late, ${issue.short.length} short`,
    },
  });
}

// --- the stock figures, against the count that made them -------------------

let audited = 0;
const suspects = [];
for (const p of products) {
  const sku = up(p.sku);
  const countedOn = calendarDay(p.last_counted_on);
  if (!sku || countedOn === null) continue;      // never counted: nothing to check it against
  audited++;

  // A receipt booked on the day of the count is taken as after it. That is a
  // convention rather than a fact, which is what the tolerance is for.
  let receivedSince = 0;
  for (const o of orders) {
    if (up(o.sku) !== sku) continue;
    const when = calendarDay(o.received_on);
    if (when === null || when < countedOn) continue;
    receivedSince += num(o.quantity_received);
  }
  let soldSince = 0;
  for (const s of sales) {
    if (up(s.sku) !== sku) continue;
    const when = calendarDay(s.date);
    if (when === null || when < countedOn) continue;
    soldSince += num(s.quantity);
  }

  const counted = num(p.counted_qty);
  const expected = round2(counted + receivedSince - soldSince);
  const onHand = num(p.on_hand);
  const drift = round2(onHand - expected);
  const tolerance = Math.max(DRIFT_UNITS, Math.ceil(Math.abs(counted) * DRIFT_PCT / 100));
  if (Math.abs(drift) <= tolerance) continue;

  suspects.push(sku);
  out.push({
    json: {
      kind: 'stock suspect',
      sku,
      product_name: p.product_name || p.name || sku,
      supplier_name: p.supplier_name || '',
      on_hand: onHand,
      expected,
      drift,
      tolerance,
      counted_qty: counted,
      last_counted_on: p.last_counted_on,
      received_since: receivedSince,
      sold_since: soldSince,
      line: `${sku}  ${p.product_name || ''}\n` +
            `    counted ${counted} on ${p.last_counted_on}, received ${receivedSince}, ` +
            `sold ${soldSince} since\n` +
            `    that makes ${expected}; the sheet says ${onHand} ` +
            `(${drift > 0 ? '+' : ''}${drift}, tolerance ${tolerance})`,
      note: `stock record off by ${drift}`,
    },
  });
}

// Always one item, whatever was found: the reorder run hangs off this output.
out.push({
  json: {
    kind: 'audit summary',
    suppliers_with_issues: issues.size,
    suspect_skus: suspects.length,
    suspects,
    products_audited: audited,
    products_never_counted: products.length - audited,
    orders_checked: orders.length,
    line: `${audited} of ${products.length} products have a count to check against; ` +
          `${suspects.length} do not add up`,
  },
});

return out;

parameters.message:
=For each of these, the last count plus what was received minus what was sold is not what the sheet says is on the shelf.

{{ $json.rows.map(r => r.line).join('\n\n') }}

Each one is marked suspect in Products and will not be reordered automatically. Count it, put the real figure in on_hand and counted_qty with today's date, and clear the stock_check cell.

