// What to order, how much of it, and from whom. The node the template is for.
//
// A low-stock alert compares one column with one number. Everything that
// makes replenishment hard is in the difference between that and this:
//
//   demand is measured over the days the product could actually be sold. A
//   fortnight out of stock is not a fortnight of no demand, and reading it
//   that way is how a line that sells out every month ends up with the
//   lowest forecast in the catalogue;
//
//   one bulk order is not the new normal. A day far above the median day is
//   set aside, and the days left are what the rate is built on;
//
//   lead time comes from our own receipts at the 80th percentile, one sample
//   per delivery and not one per line on it. The quoted figure is used only
//   when there are too few receipts to say anything, and the difference
//   between the two is worth telling the buyer about;
//
//   safety stock covers the variability of demand and of lead time together,
//   which is the only reason to hold any at all;
//
//   what is already on order counts. Ordering again because the shelf is low
//   while a lorry is on its way is how a warehouse fills up.
//
// The output is one purchase order per supplier - not one alert per SKU -
// rounded to their pack size and minimum, capped by shelf life and by the
// most cover we are willing to hold, and held back when it is under their
// minimum order value and nothing on it runs out first.

const cfg = $('Set Reorder Policy').first().json;

const clean = (bag) => (bag || []).filter((r) => r && Object.keys(r).length);
const products = clean($('Aggregate Product Data').first().json.rows);
const sales = clean($('Aggregate Sales History').first().json.rows);
const outages = clean($('Aggregate Stockout Days').first().json.rows);
const orders = clean($('Aggregate Order Pipeline').first().json.rows);
const suppliers = clean($('Aggregate Supplier Terms').first().json.rows);
const history = clean($('Aggregate Reorder History').first().json.rows);
const findings = $('Audit Stock and Open Orders').all().map((i) => i.json);

const DAY = 86400000;
const HISTORY = Math.max(7, Number(cfg.history_days) || 90);
const MIN_HISTORY = Number(cfg.min_history_days) || 21;
const REVIEW = Number(cfg.review_period_days) || 1;
const TARGET_COVER = Number(cfg.target_cover_days) || 30;
const MAX_COVER = Number(cfg.max_cover_days) || 90;
const SERVICE = Number(cfg.service_level) || 95;
const PCTL = Number(cfg.lead_time_percentile) || 80;
const MIN_SAMPLES = Math.max(1, Number(cfg.min_lead_time_samples) || 3);
const SPIKE = Number(cfg.spike_multiple) || 4;
const AUTO_UNDER = Number(cfg.auto_approve_under) || 0;
const PRICE_JUMP = Number(cfg.price_increase_pct) || 10;
const EXCEPTION_GAP = Number(cfg.days_between_exceptions) || 7;
const CURRENCY = String(cfg.default_currency || 'EUR');

const num = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const up = (v) => String(v == null ? '' : v).trim().toUpperCase();
const round2 = (v) => Math.round((Number(v) || 0) * 100) / 100;
const money = (v) => round2(v).toFixed(2);

const LEGAL = /\b(ltd|limited|llc|inc|incorporated|corp|corporation|co|company|gmbh|ag|bv|nv|sa|sas|sarl|srl|spa|oy|ab|as|aps|plc|pty|kg|ug|sl|kft|doo)\b/g;
const key = (name) => String(name || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ')
  .replace(LEGAL, ' ').replace(/\s+/g, ' ').trim();

function calendarDay(value) {
  const s = String(value == null ? '' : value).trim();
  if (!s) return null;
  if (/^\d{5}(\.\d+)?$/.test(s)) {
    const d = new Date(Date.UTC(1899, 11, 30) + Math.round(Number(s)) * DAY);
    return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()).getTime();
  }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const dayFirst = a > 12 ? true : b > 12 ? false : String(cfg.date_order) !== 'MDY';
    return new Date(Number(m[3]), (dayFirst ? b : a) - 1, dayFirst ? a : b).getTime();
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

const today = new Date();
today.setHours(0, 0, 0, 0);
const NOW = today.getTime();
const START = NOW - HISTORY * DAY;

const iso = (t) => {
  const d = new Date(t);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};
const inDays = (n) => iso(NOW + Math.round(n) * DAY);

const median = (list) => {
  if (!list.length) return 0;
  const s = [...list].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};
const stdev = (list) => {
  if (list.length < 2) return 0;
  const mean = list.reduce((a, b) => a + b, 0) / list.length;
  return Math.sqrt(list.reduce((a, b) => a + (b - mean) * (b - mean), 0) / list.length);
};

// The service level as a z. A table of five is enough: nobody sets a service
// level they cannot say out loud, and interpolating between 95 and 97 would
// be a precision the demand estimate underneath does not have.
const Z = [[85, 1.04], [90, 1.28], [95, 1.65], [97, 1.88], [98, 2.05], [99, 2.33]];
const z = Z.reduce((best, p) => (Math.abs(p[0] - SERVICE) < Math.abs(best[0] - SERVICE) ? p : best))[1];

// --- what the audit found, before any of this ------------------------------

const suspect = new Map();
for (const f of findings) {
  if (f && f.kind === 'stock suspect') suspect.set(up(f.sku), f);
}

// --- sales, by product and by day ------------------------------------------

const soldByDay = new Map();
for (const s of sales) {
  const sku = up(s.sku);
  const when = calendarDay(s.date);
  if (!sku || when === null || when < START || when >= NOW) continue;
  if (!soldByDay.has(sku)) soldByDay.set(sku, new Map());
  const days = soldByDay.get(sku);
  days.set(when, (days.get(when) || 0) + num(s.quantity));
}

// Days a product could not be sold because there was none of it. An empty
// to_date means it is still out.
const outDays = new Map();
for (const o of outages) {
  const sku = up(o.sku);
  const from = calendarDay(o.from_date);
  if (!sku || from === null) continue;
  const to = String(o.to_date || '').trim() ? calendarDay(o.to_date) : NOW - DAY;
  if (to === null) continue;
  if (!outDays.has(sku)) outDays.set(sku, new Set());
  const set = outDays.get(sku);
  for (let t = Math.max(from, START); t <= Math.min(to, NOW - DAY); t += DAY) set.add(t);
}

/** How fast it sells, over the days it could be sold at all. */
function demandFor(sku) {
  const days = soldByDay.get(sku) || new Map();
  const out = outDays.get(sku) || new Set();
  const series = [];
  for (let t = START; t < NOW; t += DAY) {
    if (out.has(t)) continue;
    series.push({ t, qty: days.get(t) || 0 });
  }

  // One wholesale order in ninety days is not a rate. The median of the days
  // that sold anything says what a normal day looks like; a day far above it
  // is set aside, with its day, so it lifts neither the total nor the count.
  const busy = series.filter((d) => d.qty > 0).map((d) => d.qty);
  const typical = median(busy);
  const spikes = [];
  const kept = [];
  for (const d of series) {
    if (typical > 0 && d.qty >= SPIKE * typical) {
      spikes.push({ on: iso(d.t), quantity: d.qty });
      continue;
    }
    kept.push(d.qty);
  }

  const sold = kept.reduce((a, b) => a + b, 0);
  return {
    rate: kept.length ? sold / kept.length : 0,
    sigma: stdev(kept),
    days_counted: kept.length,
    days_out: out.size,
    sold,
    spikes,
    typical_day: typical,
  };
}

// --- lead time, from receipts rather than from promises --------------------

const receiptsBySupplier = new Map();
const seenDelivery = new Set();
for (const o of orders) {
  const k = key(o.supplier_name);
  const sent = calendarDay(o.ordered_on);
  const got = calendarDay(o.received_on);
  if (!k || sent === null || got === null) continue;
  // A purchase order with six lines on it is one delivery, not six samples.
  const once = `${k}|${o.po_number}|${o.received_on}`;
  if (seenDelivery.has(once)) continue;
  seenDelivery.add(once);
  const days = Math.round((got - sent) / DAY);
  if (days < 0 || days > 365) continue;
  if (!receiptsBySupplier.has(k)) receiptsBySupplier.set(k, []);
  receiptsBySupplier.get(k).push({ days, received: got });
}

function leadTimeFor(k, quoted) {
  const all = (receiptsBySupplier.get(k) || []).sort((a, b) => b.received - a.received);
  const recent = all.slice(0, 12).map((r) => r.days);
  if (recent.length < MIN_SAMPLES) {
    return {
      days: Math.max(1, Math.round(quoted) || 7),
      sigma: 0,
      source: 'quoted',
      samples: recent.length,
      quoted,
    };
  }
  const sorted = [...recent].sort((a, b) => a - b);
  const at = Math.min(sorted.length - 1, Math.ceil((PCTL / 100) * sorted.length) - 1);
  return {
    days: Math.max(1, sorted[at]),
    sigma: stdev(recent),
    source: 'measured',
    samples: recent.length,
    quoted,
    typical: median(recent),
    worst: sorted[sorted.length - 1],
  };
}

// --- what is already on its way --------------------------------------------

const onOrder = new Map();
const OPEN = ['', 'open', 'ordered', 'confirmed', 'partial', 'part received', 'backordered'];
for (const o of orders) {
  const sku = up(o.sku);
  const status = String(o.status || '').trim().toLowerCase();
  if (!sku || status === 'cancelled') continue;
  if (!OPEN.includes(status) || String(o.received_on || '').trim()) continue;
  const left = num(o.quantity_ordered) - num(o.quantity_received);
  if (left <= 0) continue;
  const due = calendarDay(o.expected_on);
  const sent = calendarDay(o.ordered_on);
  const kept = onOrder.get(sku) || { quantity: 0, due: null, po_number: '', ordered: null };
  kept.quantity += left;
  if (kept.due === null || (due !== null && due < kept.due)) {
    kept.due = due;
    kept.po_number = o.po_number;
    kept.expected_on = o.expected_on;
  }
  if (kept.ordered === null || (sent !== null && sent > kept.ordered)) kept.ordered = sent;
  onOrder.set(sku, kept);
}

// What we last paid for it, to notice when the price moves.
const lastPaid = new Map();
for (const o of orders) {
  const sku = up(o.sku);
  const when = calendarDay(o.ordered_on);
  const cost = num(o.unit_cost);
  if (!sku || when === null || cost <= 0) continue;
  const kept = lastPaid.get(sku);
  if (!kept || when > kept.when) lastPaid.set(sku, { when, cost, po_number: o.po_number });
}

// An exception raised again every morning is an exception nobody reads.
const lastException = new Map();
for (const r of history) {
  if (String(r.action || '').toLowerCase() !== 'exception') continue;
  const when = calendarDay(r.run_on);
  if (when === null) continue;
  for (const sku of String(r.skus || '').split(/[,;]/).map(up).filter(Boolean)) {
    if (!lastException.has(sku) || when > lastException.get(sku)) lastException.set(sku, when);
  }
}

const exceptions = [];
const raise = (sku, why, detail) => {
  const last = lastException.get(up(sku));
  if (last !== undefined && Math.round((NOW - last) / DAY) < EXCEPTION_GAP) return;
  exceptions.push({ sku: up(sku), why, detail });
};

// --- supplier terms ---------------------------------------------------------

const supplierBy = new Map();
for (const s of suppliers) {
  const k = key(s.supplier_name || s.name);
  if (k) supplierBy.set(k, s);
}

const WEEKDAYS = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
const NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

function orderDaysOf(sup) {
  const parsed = String(sup.order_days || '').toLowerCase().split(/[^a-z]+/)
    .filter(Boolean).map((w) => WEEKDAYS[w.slice(0, 3)]).filter((n) => n !== undefined);
  return [...new Set(parsed)].sort((a, b) => a - b);
}
function daysUntilOrderDay(days) {
  if (!days.length) return 0;
  for (let i = 0; i < 7; i += 1) if (days.includes((today.getDay() + i) % 7)) return i;
  return 0;
}
// A supplier who takes orders on Monday and Thursday is reviewed every four
// days at worst, and the stock has to last that long as well as the lead
// time. This is the review period of a periodic review policy, and leaving it
// out is what makes a weekly order arrive three days late.
function reviewPeriod(days) {
  if (!days.length) return REVIEW;
  let widest = 0;
  for (let i = 0; i < days.length; i += 1) {
    const next = days[(i + 1) % days.length];
    widest = Math.max(widest, ((next - days[i] + 7) % 7) || 7);
  }
  return Math.max(REVIEW, widest);
}

// --- the next purchase order number, taken from the ledger ------------------

const year = today.getFullYear();
let sequence = 0;
for (const o of orders) {
  const m = String(o.po_number || '').match(/^PO-(\d{4})-(\d+)$/);
  if (m && Number(m[1]) === year) sequence = Math.max(sequence, Number(m[2]));
}
const nextPo = () => {
  sequence += 1;
  return `PO-${year}-${String(sequence).padStart(4, '0')}`;
};

// --- one product at a time --------------------------------------------------

const DEAD = ['discontinued', 'delisted', 'inactive', 'obsolete', 'archived'];
const bySupplier = new Map();
let skippedDead = 0;
let skippedStill = 0;

for (const p of products) {
  const sku = up(p.sku);
  if (!sku) continue;
  if (DEAD.includes(String(p.status || '').trim().toLowerCase())) {
    skippedDead += 1;
    continue;
  }

  // The audit said this row does not add up. Every number below is built on
  // that one, so there is nothing to compute: a person looks at the shelf.
  const bad = suspect.get(sku) || (String(p.stock_check || '').toLowerCase().startsWith('suspect')
    ? { line: 'the stock record is marked suspect in the sheet' } : null);
  if (bad) {
    raise(sku, 'the stock record does not add up',
      bad.line || `${sku}: the count, the receipts and the sales do not make ${num(p.on_hand)}`);
    continue;
  }

  const demand = demandFor(sku);

  // Too few sellable days to say anything. Usually this is the product that
  // has been out of stock for most of the window, which is exactly the one a
  // threshold would leave alone for ever.
  if (demand.days_counted < MIN_HISTORY) {
    if (demand.days_out > 0 || demand.sold > 0) {
      raise(sku, 'not enough history to measure demand',
        `${sku}: ${demand.days_counted} sellable days in the last ${HISTORY}, ` +
        `${demand.days_out} of them out of stock. Order this one by hand.`);
    }
    continue;
  }
  if (demand.rate <= 0) continue;

  const k = key(p.supplier_name);
  const sup = supplierBy.get(k) || {};
  const onHand = num(p.on_hand);
  const coming = onOrder.get(sku) || { quantity: 0, due: null };
  const cover = onHand / demand.rate;

  if (!k) {
    if (cover < TARGET_COVER) {
      raise(sku, 'no supplier on the product row',
        `${sku}: ${Math.floor(cover)} days of cover left and nobody to order it from.`);
    }
    continue;
  }

  const days = orderDaysOf(sup);
  const lead = leadTimeFor(k, num(sup.quoted_lead_time_days) || num(p.quoted_lead_time_days));
  const review = reviewPeriod(days);
  const sigmaLead = lead.sigma;

  // Safety stock for both kinds of variability at once: demand that moves
  // over the lead time, and a lead time that moves under the demand. Capped,
  // because a single erratic month should not buy a year of stock.
  const safety = Math.min(
    Math.ceil(z * Math.sqrt(lead.days * demand.sigma * demand.sigma
      + demand.rate * demand.rate * sigmaLead * sigmaLead)),
    Math.ceil(demand.rate * MAX_COVER),
  );
  const rop = Math.ceil(demand.rate * (lead.days + review) + safety);
  const position = onHand + coming.quantity;
  if (position > rop) {
    skippedStill += 1;
    continue;
  }

  // Something is already on its way. If it lands before the shelf empties,
  // the answer is to wait: ordering again because the shelf looks low is how
  // a warehouse ends up holding two of everything.
  const arriving = coming.quantity > 0
    ? (coming.due === null ? lead.days : Math.round((coming.due - NOW) / DAY))
    : null;
  let expedited = '';
  if (coming.quantity > 0) {
    if (cover >= arriving) {
      skippedStill += 1;
      continue;
    }
    expedited = `${coming.po_number || 'the open order'} lands in ${arriving} days and the ` +
      `shelf empties in ${Math.floor(cover)}`;
  }

  const pack = Math.max(1, num(p.pack_size) || 1);
  const moq = Math.max(0, num(p.moq));
  const wanted = demand.rate * (lead.days + review + TARGET_COVER) + safety - position;
  let quantity = Math.ceil(Math.ceil(wanted) / pack) * pack;
  if (quantity <= 0) continue;

  const notes = [];
  if (quantity < moq) {
    quantity = Math.ceil(moq / pack) * pack;
    notes.push(`their minimum is ${moq}`);
  }

  // Two ceilings, and they are not the same thing: how much the shelf holds,
  // and how long the goods last once they are on it.
  const shelfLife = num(p.shelf_life_days);
  const maxStock = num(p.max_stock);
  let ceiling = Infinity;
  if (maxStock > 0) ceiling = Math.min(ceiling, maxStock - position);
  if (shelfLife > 0) ceiling = Math.min(ceiling, Math.floor(demand.rate * shelfLife) - position);
  if (quantity > ceiling) {
    const room = Math.floor(Math.max(0, ceiling) / pack) * pack;
    if (room <= 0 || room < moq) {
      raise(sku, 'their minimum does not fit',
        `${sku}: we need ${Math.ceil(wanted)}, their minimum is ${moq || pack} and there is ` +
        `room for ${Math.max(0, Math.floor(ceiling))} before ` +
        `${maxStock > 0 && maxStock - position <= ceiling ? 'the shelf is full' : 'it goes off'}.`);
      continue;
    }
    quantity = room;
    notes.push('capped by shelf life or maximum stock');
  }

  const coverAfter = (position + quantity) / demand.rate;
  if (coverAfter > MAX_COVER) {
    raise(sku, 'the minimum order is more than we can hold',
      `${sku}: ${quantity} units is ${Math.round(coverAfter)} days of cover at ` +
      `${round2(demand.rate)} a day, and the ceiling is ${MAX_COVER}. ` +
      `Their minimum is ${moq}, the pack is ${pack}.`);
    continue;
  }

  const unitCost = num(p.unit_cost) || (lastPaid.get(sku) || {}).cost || 0;
  const paid = lastPaid.get(sku);
  const jump = paid && paid.cost > 0 ? round2(((unitCost - paid.cost) / paid.cost) * 100) : 0;

  const line = {
    sku,
    product_name: p.product_name || p.name || sku,
    quantity,
    unit_cost: round2(unitCost),
    line_value: round2(quantity * unitCost),
    on_hand: onHand,
    on_order: coming.quantity,
    demand_per_day: round2(demand.rate),
    cover_days: Math.floor(cover),
    runs_out_on: inDays(Math.floor(cover)),
    lead_time_days: lead.days,
    lead_time_source: lead.source,
    review_days: review,
    safety_stock: safety,
    reorder_point: rop,
    cover_after_days: Math.round(coverAfter),
    days_out_of_stock: demand.days_out,
    spikes_ignored: demand.spikes.length,
    price_move_pct: jump,
    critical: cover < lead.days,
    expedited,
    note: notes.join('; '),
  };
  if (!bySupplier.has(k)) {
    bySupplier.set(k, {
      supplier_name: p.supplier_name,
      supplier: sup,
      lead,
      order_days: days,
      review,
      lines: [],
    });
  }
  bySupplier.get(k).lines.push(line);
}

// --- one purchase order per supplier ---------------------------------------

const pad = (s, n) => String(s == null ? '' : s).padEnd(n).slice(0, n);
const padl = (s, n) => String(s == null ? '' : s).padStart(n);

const out = [];
for (const [k, group] of bySupplier) {
  const sup = group.supplier;
  const lines = group.lines.sort((a, b) => a.cover_days - b.cover_days);
  const value = round2(lines.reduce((a, l) => a + l.line_value, 0));
  const currency = String(sup.currency || CURRENCY);
  const email = String(sup.email || '').trim();
  const critical = lines.filter((l) => l.critical);
  const waitDays = daysUntilOrderDay(group.order_days);
  const minValue = num(sup.min_order_value);
  const known = (receiptsBySupplier.get(k) || []).length > 0;
  const jumps = lines.filter((l) => l.price_move_pct > PRICE_JUMP);

  if (!email) {
    for (const l of lines) {
      raise(l.sku, 'no address for the supplier',
        `${l.sku}: ${l.quantity} units to order from ${group.supplier_name}, and no email ` +
        `address on their row.`);
    }
    continue;
  }

  const table = [
    `${pad('SKU', 14)}${pad('Product', 28)}${padl('Qty', 7)}${padl('Unit', 10)}${padl('Line', 11)}`,
  ];
  for (const l of lines) {
    table.push(`${pad(l.sku, 14)}${pad(l.product_name, 28)}${padl(l.quantity, 7)}` +
      `${padl(money(l.unit_cost), 10)}${padl(money(l.line_value), 11)}`);
  }
  table.push(`${pad('', 14)}${pad('', 28)}${padl('', 7)}${padl('Total', 10)}` +
    `${padl(`${currency} ${money(value)}`, 11)}`);

  const why = [];
  why.push(`Lead time ${group.lead.days} days, ` +
    (group.lead.source === 'measured'
      ? `the 80th percentile of the last ${group.lead.samples} deliveries` +
        (group.lead.quoted && group.lead.days > group.lead.quoted
          ? ` - they quote ${group.lead.quoted}`
          : '')
      : `as quoted: only ${group.lead.samples} receipt(s) on file`) + '.');
  why.push(`Review period ${group.review} day(s).`);
  for (const l of lines) {
    const bits = [`${l.sku}: ${l.quantity} units, ${l.cover_days} days of cover left ` +
      `at ${l.demand_per_day} a day, reorder point ${l.reorder_point} ` +
      `(safety stock ${l.safety_stock}), ${l.cover_after_days} days of cover after this`];
    if (l.on_order) bits.push(`${l.on_order} already on order`);
    if (l.expedited) bits.push(l.expedited);
    if (l.days_out_of_stock) bits.push(`${l.days_out_of_stock} days out of stock, not counted`);
    if (l.spikes_ignored) bits.push(`${l.spikes_ignored} one-off day(s) set aside`);
    if (l.price_move_pct) bits.push(`unit cost ${l.price_move_pct > 0 ? 'up' : 'down'} ` +
      `${Math.abs(l.price_move_pct)}% on the last order`);
    if (l.note) bits.push(l.note);
    why.push(`  ${bits.join('; ')}.`);
  }

  // Under their minimum order value, and nothing on it is urgent: the run
  // tomorrow will have more on it, and one order of 250 costs less to handle
  // than five of 50.
  let action = 'order';
  let reason = '';
  if (waitDays > 0 && !critical.length) {
    action = 'hold';
    reason = `${group.supplier_name} take orders on ` +
      `${group.order_days.map((d) => NAMES[d]).join(' and ')}; this goes out in ${waitDays} day(s).`;
  } else if (minValue > 0 && value < minValue && !critical.length) {
    action = 'hold';
    reason = `${currency} ${money(value)} against their ${currency} ${money(minValue)} ` +
      `minimum, and nothing on it runs out first.`;
  } else if (AUTO_UNDER > 0 && value > AUTO_UNDER) {
    action = 'approve';
    reason = `${currency} ${money(value)} is over the ${currency} ${money(AUTO_UNDER)} ` +
      `this workflow sends on its own.`;
  } else if (!known) {
    action = 'approve';
    reason = `${group.supplier_name} has no delivery on file: nothing has ever been ` +
      `received from them, so the lead time is their own figure.`;
  } else if (jumps.length) {
    action = 'approve';
    reason = `${jumps.map((l) => `${l.sku} is ${l.price_move_pct}% dearer than last time`)
      .join('; ')}.`;
  }

  if (action !== 'hold' && minValue > 0 && value < minValue && critical.length) {
    why.push(`Under their ${currency} ${money(minValue)} minimum, sent anyway: ` +
      `${critical.map((l) => l.sku).join(', ')} runs out before a delivery could arrive.`);
  }

  // Free carriage is worth having only if the extra units would have been
  // bought anyway. Nothing is added here - the buyer is told, and decides.
  const freeOver = num(sup.free_shipping_over);
  if (freeOver > 0 && value < freeOver) {
    const room = lines
      .map((l) => ({
        line: l,
        units: Math.max(0, Math.floor((MAX_COVER - l.cover_after_days) * l.demand_per_day)),
      }))
      .filter((c) => c.units > 0 && c.line.unit_cost > 0)
      .sort((a, b) => b.line.demand_per_day - a.line.demand_per_day)[0];
    if (room) {
      const need = Math.ceil((freeOver - value) / room.line.unit_cost);
      if (need <= room.units) {
        why.push(`Carriage is free over ${currency} ${money(freeOver)}: ${need} more of ` +
          `${room.line.sku} would reach it and still be inside ${MAX_COVER} days of cover.`);
      }
    }
  }

  const poNumber = nextPo();
  const expected = inDays(group.lead.days);
  out.push({
    json: {
      kind: 'order',
      action,
      reason,
      supplier_name: group.supplier_name,
      supplier_email: email,
      contact_name: String(sup.contact_name || '').trim(),
      currency,
      po_number: poNumber,
      ordered_on: iso(NOW),
      expected_on: expected,
      order_value: value,
      line_count: lines.length,
      skus: lines.map((l) => l.sku).join(', '),
      critical_skus: critical.map((l) => l.sku).join(', '),
      lead_time_days: group.lead.days,
      lead_time_source: group.lead.source,
      subject_line: `Purchase order ${poNumber} - ${lines.length} line(s), ` +
        `${currency} ${money(value)}`,
      table: table.join('\n'),
      internal: why.join('\n'),
      // The whole working, not only the columns the sheet takes: what ends
      // up in Purchase orders is what PO_LINE_COLUMNS maps, and the rest is
      // here to be read in an execution when somebody asks why.
      lines: lines.map((l) => ({
        ...l,
        line_key: `${poNumber}|${l.sku}`,
        po_number: poNumber,
        supplier_name: group.supplier_name,
        ordered_on: iso(NOW),
        expected_on: expected,
      })),
    },
  });
}

if (exceptions.length) {
  out.push({
    json: {
      kind: 'exception',
      action: 'exception',
      supplier_name: '',
      skus: exceptions.map((e) => e.sku).join(', '),
      line_count: exceptions.length,
      order_value: 0,
      currency: CURRENCY,
      subject_line: `Replenishment: ${exceptions.length} line(s) need you`,
      reason: exceptions.map((e) => e.why).join('; '),
      report: exceptions.map((e) => `- ${e.detail}`).join('\n\n'),
      rows: exceptions,
    },
  });
}

if (!out.length) {
  out.push({
    json: {
      kind: 'nothing',
      action: 'nothing',
      supplier_name: '',
      skus: '',
      line_count: 0,
      order_value: 0,
      currency: CURRENCY,
      reason: `${products.length - skippedDead} live product(s) checked, ` +
        `${skippedStill} of them above their reorder point, ` +
        `${skippedDead} discontinued.`,
    },
  });
}

return out;

