parameters.jsCode:
// Everything below the reply is our own email. That is the trap here.
//
// A supplier confirming an order writes three lines and hits send, and their
// mail client keeps the whole of ours underneath: "200 units, expected 4
// March". Hand that to a model and ask it what they confirmed, and it has two
// answers to choose from - theirs and ours - with ours written in the more
// confident language, because we wrote it as a statement and they wrote
// theirs as an apology. It picks ours often enough to matter, and what it
// picks is always the reassuring one: the quantity we wanted, the date we
// asked for. A workflow that reads its own outbox and calls it a confirmation
// is worse than one that reads nothing.
//
// So the thread is cut off before the model sees it, and the rule is: an
// identifier may come out of the quoted part, a fact may not. The purchase
// order number is an identifier - if the only place it appears is the subject
// line or the quote, that is still the order they are replying about. The
// quantity, the date and the price are facts, and they are only ever taken
// from what this person typed today.
//
// Whether a person typed anything at all is settled here too, by the headers
// (RFC 3834), because an out-of-office answering a purchase order is not a
// confirmation of it.

const out = [];

const CUT_MARKERS = [
  /^\s*-{2,}\s*(original message|forwarded message|ursprüngliche nachricht|messaggio originale)\s*-{2,}/i,
  /^\s*_{5,}\s*$/,
  /^\s*(le|il giorno|am|op|el)\b.{0,200}\b(a écrit|ha scritto|schrieb|schreef|escribió)\s*:?\s*$/i,
  /^\s*(sent from my|get outlook for)\b/i,
];

/** The reply, cut where our own email starts underneath it. */
function splitQuote(text) {
  const lines = String(text == null ? '' : text).replace(/\r\n/g, '\n').split('\n');
  let cut = -1;

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];

    if (/^\s*>/.test(line)) { cut = i; break; }
    if (CUT_MARKERS.some((re) => re.test(line))) { cut = i; break; }

    // "On Tuesday, 3 March 2026 at 10:02, Buyer <buyer@...> wrote:" - which
    // the client may well have wrapped over two or three lines.
    if (/^\s*on\b/i.test(line)) {
      const joined = lines.slice(i, i + 3).join(' ');
      if (/\bwrote\s*:\s*$/i.test(line) || /\bwrote\s*:/i.test(joined)) { cut = i; break; }
    }

    // The Outlook header block: From: on its own is a weak signal, so it only
    // counts when one of its neighbours is Sent:, Date: or To:.
    if (/^\s*from\s*:\s*\S/i.test(line)
        && lines.slice(i + 1, i + 4).some((l) => /^\s*(sent|date|to|subject)\s*:/i.test(l))) {
      cut = i;
      break;
    }
  }

  if (cut === -1) return { fresh: lines.join('\n').trim(), quoted: '' };
  return {
    fresh: lines.slice(0, cut).join('\n').trim(),
    quoted: lines.slice(cut).join('\n').trim(),
  };
}

// RFC 3834, and what the rest of the world does instead of it.
function automatic(mail) {
  const raw = mail.headers || {};
  const pairs = Array.isArray(raw) ? raw.map((h) => [h.name, h.value]) : Object.entries(raw);
  const headers = {};
  for (const [name, value] of pairs) {
    headers[String(name).toLowerCase()] = String(value == null ? '' : value).trim().toLowerCase();
  }
  const header = (name) => headers[name] || '';

  const submitted = header('auto-submitted');
  if (submitted && submitted !== 'no') return `the Auto-Submitted: ${submitted} header`;
  if (header('x-autoreply') || header('x-autorespond') || header('x-auto-response-suppress')) {
    return 'an auto-responder header';
  }
  if (['bulk', 'auto_reply', 'list', 'junk'].includes(header('precedence'))) {
    return `the Precedence: ${header('precedence')} header`;
  }

  const subject = String(mail.subject || '').toLowerCase()
    .replace(/^((re|fwd?|aw|sv|vs|antwort)\s*:\s*)+/g, '').trim();
  if (/^(auto(matic)?[ -]?(reply|response|answer)|autoreply|out of (the )?office|ooo\b|absence|undeliverable|undelivered|delivery status notification|mail delivery (failed|subsystem))/.test(subject)) {
    return 'the subject line';
  }
  return '';
}

/** Purchase order numbers, as written, wherever they appear. */
function poNumbers(text) {
  const found = [];
  const re = /\bP\.?O\.?[-\s#]?(\d{2,4})(?:[-\s](\d{1,6}))?\b/gi;
  let m = re.exec(String(text || ''));
  while (m) {
    found.push(m[2] ? `PO-${m[1]}-${m[2]}` : `PO-${m[1]}`);
    m = re.exec(String(text || ''));
  }
  return [...new Set(found.map((v) => v.toUpperCase()))];
}

// The emails come from the trigger by name, not from this node's input. What
// arrives here is one folded item carrying the Purchase orders tab, because
// the sheet had to be read before the reply could be compared with anything;
// the reply itself is three nodes back.
for (const item of $('When a Supplier Replies').all()) {
  const mail = item.json || {};
  const subject = String(mail.subject || '');
  const body = String(mail.text || mail.textPlain || mail.snippet || '');
  const { fresh, quoted } = splitQuote(body);
  const reason = automatic(mail);

  out.push({
    json: {
      message_id: mail.id || mail.messageId || '',
      thread_id: mail.threadId || '',
      from: mail.from || (mail.headers || {}).from || '',
      subject,
      is_auto: !!reason,
      auto_reason: reason,
      nothing_new: !reason && !fresh,
      fresh_text: fresh || '(nothing but the quoted thread)',
      quoted_text: quoted,
      // In this order on purpose: what they typed, then the subject line,
      // then our own email underneath. Identity only - never a quantity,
      // never a date.
      po_in_reply: poNumbers(fresh),
      po_in_subject: poNumbers(subject),
      po_in_quote: poNumbers(quoted),
    },
  });
}

return out;

// What the supplier actually agreed to, against what we asked for.
//
// "Confirmed" is three different answers. The same word covers the order as
// placed, the order minus a third of it, and the order three weeks later than
// we need it - and only the first of those is news that belongs in a sheet
// without a person seeing it.
//
// So the confirmation is compared line by line with the order, and the test
// is never "is this different". It is: does the difference reach past the day
// the shelf empties. The purchase order line carries the two numbers needed
// to answer that - the demand per day it was ordered against, and the date
// the stock runs out - written there when the order went out, so this node
// does not have to recompute a forecast to read an email.
//
//   a date inside that day          accepted, the sheet takes the new date
//   a date past it                  the buyer is told how many days we are
//                                   short, and the line is flagged at risk
//   a quantity that still covers    accepted, the pipeline takes the smaller
//                                   number so the next run can top it up
//   a quantity that does not        the buyer, with the arithmetic
//   a price over tolerance          the buyer: a confirmation is not the
//                                   place to agree to a price rise
//
// An out-of-office and a reply that quotes our own order back at us are not
// confirmations of anything, and both are settled before the comparison.

const cfg = $('Set Confirmation Rules').first().json;
const clean = (bag) => (bag || []).filter((r) => r && Object.keys(r).length);
const openLines = clean($('Aggregate Open Order Lines').first().json.rows);
const read = $input.all();

// The stripped emails are fetched by name rather than taken from this node's
// input: what arrives here is the extractor's output, which has thrown away
// the headers, and it is the headers that say whether a person wrote it.
// Same order, same index.
let mails = [];
try {
  mails = $('Strip the Quoted Reply').all();
} catch (e) {
  mails = [];
}

const DAY = 86400000;
const PRICE_TOLERANCE = Number(cfg.price_tolerance_pct) || 2;
const DATE_TOLERANCE = Number(cfg.date_tolerance_days) || 0;
const MIN_COVER = Number(cfg.min_cover_days) || 5;

const num = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const up = (v) => String(v == null ? '' : v).trim().toUpperCase();
const round2 = (v) => Math.round((Number(v) || 0) * 100) / 100;
const poKey = (v) => up(v).replace(/[\s#]+/g, '').replace(/^P\.?O\.?\.?-?/, 'PO-');

function calendarDay(value) {
  const s = String(value == null ? '' : value).trim();
  if (!s) return null;
  if (/^\d{5}(\.\d+)?$/.test(s)) {
    const d = new Date(Date.UTC(1899, 11, 30) + Math.round(Number(s)) * DAY);
    return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()).getTime();
  }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const dayFirst = a > 12 ? true : b > 12 ? false : String(cfg.date_order) !== 'MDY';
    return new Date(Number(m[3]), (dayFirst ? b : a) - 1, dayFirst ? a : b).getTime();
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

const today = new Date();
today.setHours(0, 0, 0, 0);
const NOW = today.getTime();
const iso = (t) => {
  const d = new Date(t);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

const RECEIVED = ['received', 'closed', 'complete', 'completed', 'cancelled'];
const byPo = new Map();
for (const row of openLines) {
  const po = poKey(row.po_number);
  if (!po) continue;
  if (!byPo.has(po)) byPo.set(po, []);
  byPo.get(po).push(row);
}

const out = [];
const hand = (mail, why, detail, extra) => ({
  json: {
    action: 'follow-up',
    from: mail.from || '',
    subject: mail.subject || '',
    why,
    detail,
    fresh_text: mail.fresh_text || '',
    ...extra,
  },
});

for (let i = 0; i < read.length; i += 1) {
  const said = (read[i].json && read[i].json.output) || read[i].json || {};
  const mail = (mails[i] && mails[i].json) || {};

  if (mail.is_auto) {
    out.push({
      json: {
        action: 'ignore',
        from: mail.from || '',
        subject: mail.subject || '',
        why: `an automatic reply, by ${mail.auto_reason}`,
        detail: 'Nothing was written to the sheet and no order was changed.',
      },
    });
    continue;
  }

  if (mail.nothing_new) {
    out.push(hand(mail, 'the reply had nothing in it but our own email',
      'Somebody hit reply and sent it. Whatever they meant is not in the message.'));
    continue;
  }

  // Identity may come out of the quote; facts may not.
  const candidates = [
    ...(said.po_number ? [poKey(said.po_number)] : []),
    ...(mail.po_in_reply || []),
    ...(mail.po_in_subject || []),
    ...(mail.po_in_quote || []),
  ];
  const po = candidates.find((c) => byPo.has(c));
  if (!po) {
    out.push(hand(mail, 'no open order matches this reply',
      candidates.length
        ? `They mention ${[...new Set(candidates)].join(', ')}; none of those is open in the ` +
          `Purchase orders tab.`
        : 'There is no purchase order number in the reply, the subject line or the thread.'));
    continue;
  }

  const rows = byPo.get(po);
  if (rows.every((r) => RECEIVED.includes(String(r.status || '').trim().toLowerCase()))) {
    out.push({
      json: {
        action: 'ignore',
        from: mail.from || '',
        subject: mail.subject || '',
        why: `${po} is already closed`,
        detail: 'The goods are in. A confirmation arriving now changes nothing.',
      },
    });
    continue;
  }

  // Which line of it. One line, and there is no question; several, and they
  // have to say, because "confirmed, 120" on a four-line order is not an
  // instruction anybody should carry out.
  const wantedSku = up(said.sku);
  let row = null;
  if (wantedSku) row = rows.find((r) => up(r.sku) === wantedSku) || null;
  if (!row && rows.length === 1) [row] = rows;
  if (!row) {
    out.push(hand(mail, `${po} has ${rows.length} lines and the reply does not say which`,
      `Lines on it: ${rows.map((r) => up(r.sku)).join(', ')}.`, { po_number: po }));
    continue;
  }

  const ordered = num(row.quantity_ordered);
  const orderedCost = num(row.unit_cost);
  const rate = num(row.demand_per_day);
  const runsOut = calendarDay(row.runs_out_on);
  const expected = calendarDay(row.expected_on);

  const confirmedQty = said.confirmed_quantity === '' || said.confirmed_quantity == null
    ? null : num(said.confirmed_quantity);
  const confirmedDay = calendarDay(said.confirmed_date);
  const confirmedCost = said.confirmed_unit_price === '' || said.confirmed_unit_price == null
    ? null : num(said.confirmed_unit_price);

  const arrival = confirmedDay === null ? expected : confirmedDay;
  const quantity = confirmedQty === null ? ordered : confirmedQty;
  const shortBy = round2(Math.max(0, ordered - quantity));
  const slip = arrival !== null && expected !== null
    ? Math.round((arrival - expected) / DAY) : 0;
  const priceMove = orderedCost > 0 && confirmedCost !== null && confirmedCost > 0
    ? round2(((confirmedCost - orderedCost) / orderedCost) * 100) : 0;

  const trouble = [];

  // The question is never "did anything change". It is whether the change
  // reaches past the day the shelf empties.
  let shortDays = 0;
  if (arrival !== null && runsOut !== null && arrival > runsOut) {
    shortDays = Math.round((arrival - runsOut) / DAY);
    trouble.push(`it lands on ${iso(arrival)} and ${up(row.sku)} runs out on ` +
      `${row.runs_out_on}: ${shortDays} day(s) with an empty shelf`);
  }
  if (shortBy > 0) {
    const coverLost = rate > 0 ? shortBy / rate : 0;
    const coverLeft = num(row.cover_after_days) - coverLost;
    if (rate > 0 && coverLeft < MIN_COVER) {
      trouble.push(`${shortBy} units short leaves ${Math.max(0, Math.floor(coverLeft))} ` +
        `day(s) of cover, under the ${MIN_COVER} this workflow will accept`);
    }
  }
  if (priceMove > PRICE_TOLERANCE) {
    trouble.push(`the unit price is ${priceMove}% over the order ` +
      `(${orderedCost} to ${confirmedCost}): a confirmation is not the place to agree to that`);
  }

  const changes = [];
  if (shortBy > 0) changes.push(`${quantity} of ${ordered} units`);
  if (slip > 0) changes.push(`${slip} day(s) later than asked, ${iso(arrival)}`);
  if (slip < 0) changes.push(`${Math.abs(slip)} day(s) earlier, ${iso(arrival)}`);
  if (priceMove) changes.push(`unit price ${priceMove > 0 ? 'up' : 'down'} ` +
    `${Math.abs(priceMove)}%`);

  const common = {
    po_number: row.po_number,
    line_key: row.line_key || `${row.po_number}|${up(row.sku)}`,
    sku: up(row.sku),
    product_name: row.product_name || '',
    supplier_name: row.supplier_name || '',
    from: mail.from || '',
    subject: mail.subject || '',
    ordered_quantity: ordered,
    confirmed_quantity: quantity,
    short_by: shortBy,
    ordered_expected_on: row.expected_on || '',
    confirmed_expected_on: arrival === null ? row.expected_on || '' : iso(arrival),
    slip_days: slip,
    unit_cost: confirmedCost === null ? orderedCost : confirmedCost,
    price_move_pct: priceMove,
    runs_out_on: row.runs_out_on || '',
    days_uncovered: shortDays,
    confirmed_on: iso(NOW),
    changes: changes.join('; ') || 'nothing changed: in full, on the date we asked for',
    summary: String(said.summary || '').trim(),
  };

  if (trouble.length) {
    out.push({
      json: {
        ...common,
        action: 'escalate',
        status: 'at risk',
        why: trouble.join('; '),
        detail: `${common.supplier_name} answered on ${po}.\n\n` +
          `Ordered:   ${ordered} units, wanted by ${row.expected_on}\n` +
          `Confirmed: ${quantity} units, ${iso(arrival)}\n` +
          `Sells at:  ${rate} a day, on the shelf until ${row.runs_out_on}\n\n` +
          `${trouble.map((t) => `- ${t}`).join('\n')}`,
      },
    });
    continue;
  }

  out.push({
    json: {
      ...common,
      action: 'accept',
      status: 'confirmed',
      why: changes.length
        ? `accepted: ${changes.join('; ')}, and it still lands before the shelf empties`
        : 'confirmed as ordered',
      // The pipeline takes the smaller number rather than the one we asked
      // for: tomorrow's run reads this tab, and it should see what is really
      // coming, so it can make up the difference somewhere else.
      detail: shortBy > 0
        ? `The order line now says ${quantity}, not ${ordered}. Tomorrow's run reads that ` +
          `and tops up if it has to.`
        : 'Nothing to do: the sheet has the confirmed date.',
    },
  });
}

return out;

